-- How-to videos course (generated by scripts/gen-howto-course.py - safe to re-run).
insert into public.training_courses (slug, title, blurb, audience, status, sort_order)
values ('how-to-videos', 'How-to videos',
  'Short videos showing how to use each Hub module. Watch at least 90% of a video to complete it: 5 points per video and a 100-point bonus when you finish them all.',
  'All staff', 'published', 1000)
on conflict (slug) do update set
  title = excluded.title, blurb = excluded.blurb, audience = excluded.audience,
  status = 'published', updated_at = now();

-- 1. Event Packets
update public.training_lessons l set
  title = 'Event Packets how-to', body = 'A short how-to for Event Packets. You can also open it any time from the Watch how-to video link at the top of the page (/event-packets).', sort_order = 10, updated_at = now()
from public.training_courses c
where c.slug = 'how-to-videos' and l.course_id = c.id and l.resource_href = 'https://vident-productions.b-cdn.net/vident-howto/event-packets.mp4';
insert into public.training_lessons (course_id, sort_order, title, body, resource_href, resource_label)
select c.id, 10, 'Event Packets how-to', 'A short how-to for Event Packets. You can also open it any time from the Watch how-to video link at the top of the page (/event-packets).', 'https://vident-productions.b-cdn.net/vident-howto/event-packets.mp4', ''
from public.training_courses c where c.slug = 'how-to-videos'
  and not exists (select 1 from public.training_lessons l
    where l.course_id = c.id and l.resource_href = 'https://vident-productions.b-cdn.net/vident-howto/event-packets.mp4');

